// Every activity below is an original study sprint, not a copied provider syllabus.
const activities=[];
function add(id,title,skill,level,hours,stage,prereqs,source,deliverable){activities.push({id,title,skill,level,hours,stage,prereqs,source,deliverable,access:'free',kind:'Original study sprint'});}
add('network-1','Systems & network essentials','network',2,18,0,[],'thm','Explain a packet capture, DNS lookup, process tree, and file permissions in a short lab notebook.');
add('security-1','Security principles in practice','security',2,12,0,[],'cc','Write a scoped lab authorization, an asset inventory, and a simple risk-to-control explanation.');
