add('ai-1','AI literacy for security practitioners','ai',2,12,1,['security-1'],'htb','Draw the boundaries between model, retrieval, tools, and host code; record five model limitations.');
add('judgment-1','Verify outputs & bound agent autonomy','judgment',3,10,1,['ai-1'],'htb-aug','Audit ten synthetic AI claims against evidence and implement a human approval gate for sensitive actions.');
add('detection-1','Investigate telemetry & build a detection','detection',3,24,2,['network-1','security-1'],'letsdefend','Write and test a detection query; include false positives, expected fields, and evidence references.');
add('response-1','Reconstruct an incident & justify containment','response',3,24,2,['network-1','security-1'],'offsec-path','Deliver an artifact-backed timeline, triage log, containment plan, and recovery checks.');
add('offense-1','Run an authorized security assessment','offense',3,32,2,['network-1','security-1'],'htb','Produce a scoped test report with reproducible findings, mitigations, and retest outcomes.');
