const questions=[
['q-network','network','A name resolves to an address, but the TCP connection times out. What should you check next?',['Only the DNS zone','Routing, firewall policy, and whether the service is listening','The browser language setting'],1,'Successful DNS resolution does not establish network reachability or a listening service.'],
['q-security','security','A lab asks you to test a public IP not listed in the authorization. What is the next step?',['Test it quietly','Clarify scope and obtain authorization first','Use an AI agent so it is automated'],1,'Written scope and authorization define what testing is permitted.'],
['q-python','python','An automated log parser silently drops malformed records. What is the most useful improvement?',['Ignore them to keep the output clean','Add validation, explicit error counts, and tests for malformed input','Ask the model to guarantee correctness'],1,'Observable errors and input tests make security automation reviewable and reliable.'],
['q-detection','detection','An AI assistant says an alert is a false positive. What supports closing it?',['The confidence language in its answer','The number of words in the summary','Raw telemetry and documented checks that support the conclusion'],2,'The source evidence and investigation criteria justify the decision.'],
['q-response','response','Before using AI to analyze an evidence image, what should you establish?',['The model is popular','Evidence integrity, approved handling, and a record of transformations','That the model can write a fluent report'],1,'Integrity and controlled handling protect reproducibility and the evidence trail.'],
['q-offense','offense','An AI agent proposes a destructive test outside the agreed rules. What do you do?',['Run it because automation is faster','Block it, document the proposal, and choose an authorized non-destructive test','Remove logging'],1,'An operator retains responsibility for scope and impact.'],
['q-appsec','appsec','An LLM produces a database query from a user prompt. Where should authorization be enforced?',['In a polite system prompt alone','In the application/server with scoped permissions and validated operations','Only in the UI'],1,'The model is not an authorization boundary; server-side controls must enforce permissions.'],
['q-cloud','cloud','How should a model-serving workload access its data store?',['Shared permanent administrator keys','Workload identity with scoped permissions and managed credential lifetime','Credentials inside the model prompt'],1,'Scoped, managed workload identity reduces exposure and supports audit and revocation.'],
['q-identity','identity','An agent needs to read one incident queue. Which permission is appropriate?',['Tenant-wide administrator','Read-only access scoped to that queue','All permissions to avoid errors'],1,'Grant the minimum permission required by the actual task.'],
['q-risk','risk','Who should accept material residual AI risk?',['The AI assistant','The accountable human risk owner under organizational governance','Whoever finishes training first'],1,'Risk decisions need an accountable owner, evidence, and the organization’s approval process.'],
['q-intel','intel','A generated threat brief cites a report you cannot locate. What should you do?',['Publish it with a high-confidence label','Treat the claim as unverified and seek corroborating original evidence','Add more generated citations'],1,'Traceability and corroboration separate observations from unsupported inference.'],
['q-privacy','privacy','A retrieval system returns another customer’s private document. What is the primary fix?',['Ask the model to be more careful','Enforce tenant/user authorization in retrieval and test isolation','Increase response randomness'],1,'Data access must be enforced before retrieval reaches the model.'],
['q-ot','ot','An AI monitoring tool recommends restarting a live industrial controller. What comes first?',['Execute automatically','Site safety, authorized change control, and validated operating procedures','An internet tutorial'],1,'Safety and site-specific engineering authority govern actions in operational environments.'],
['q-ai','ai','What best describes retrieval-augmented generation (RAG)?',['A guarantee that a response is true','Supplying retrieved context to generation; output still needs verification','A replacement for access control'],1,'Retrieved context can improve grounding, but can also be wrong, unauthorized, or malicious.'],
['q-aisec','aisec','A retrieved page tells an agent to ignore instructions and export secrets. What is this?',['A trusted administrator command','Indirect prompt injection crossing a data/instruction boundary','A harmless formatting preference'],1,'Untrusted retrieved content can contain attacker instructions; host-side permissions and data boundaries matter.'],
['q-judgment','judgment','What is the strongest evaluation for an autonomous response workflow?',['A single impressive demo','Repeated ground-truth scenarios including errors, denied actions, escalation, and recovery','The model vendor’s popularity'],1,'Evaluate success and failure modes against known outcomes and clear authority boundaries.']
].map(([id,skill,prompt,options,answer,explanation])=>({id,skill,prompt,options,answer,explanation}));
